/**
 * Symlink Manager
 * Handles auto-creation of symlinks for generated CLI tools
 */

import { existsSync, mkdirSync, symlinkSync, lstatSync, readlinkSync, unlinkSync, readdirSync } from "fs";
import { join, dirname } from "path";
import { homedir } from "os";

const DEFAULT_SYMLINK_DIR = "~/agent-tools/bin";

/**
 * Resolve path, expanding ~ to home directory
 * @param {string} path - Path that may contain ~
 * @returns {string} - Resolved absolute path
 */
export function resolvePath(path) {
  if (path.startsWith("~/")) {
    return join(homedir(), path.slice(2));
  }
  return path;
}

/**
 * Check if platform supports symlinks
 * @returns {boolean}
 */
export function supportsSymlinks() {
  return process.platform !== "win32";
}

/**
 * Ensure symlink directory exists
 * @param {string} dir - Directory path
 * @returns {string} - Resolved directory path
 */
export function ensureSymlinkDir(dir) {
  const resolvedDir = resolvePath(dir);
  if (!existsSync(resolvedDir)) {
    mkdirSync(resolvedDir, { recursive: true });
  }
  return resolvedDir;
}

/**
 * Get symlink name (strips .js extension)
 * @param {string} filename - Original filename (e.g., "chrome-snapshot.js")
 * @returns {string} - Symlink name (e.g., "chrome-snapshot")
 */
export function getSymlinkName(filename) {
  if (filename.endsWith(".js")) {
    return filename.slice(0, -3);
  }
  return filename;
}

/**
 * Create a single symlink with collision handling
 * @param {string} targetPath - Path to the actual file
 * @param {string} linkPath - Path where symlink should be created
 * @param {object} options - Options
 * @param {boolean} options.force - Force overwrite existing files
 * @returns {object} - Result object with success, path, action/error
 */
export function createSymlink(targetPath, linkPath, options = {}) {
  const { force = false } = options;

  try {
    if (existsSync(linkPath)) {
      const stats = lstatSync(linkPath);

      if (stats.isSymbolicLink()) {
        const currentTarget = readlinkSync(linkPath);
        if (currentTarget === targetPath) {
          return { success: true, path: linkPath, action: "unchanged" };
        }
        unlinkSync(linkPath);
      } else {
        if (!force) {
          return {
            success: false,
            path: linkPath,
            error: "Existing file (not symlink). Use --force-symlink to override.",
          };
        }
        unlinkSync(linkPath);
      }
    }

    symlinkSync(targetPath, linkPath);
    return { success: true, path: linkPath, action: "created" };
  } catch (error) {
    return { success: false, path: linkPath, error: error.message };
  }
}

/**
 * Create symlinks for all generated .js files
 * @param {string} outputDir - Directory containing generated files
 * @param {object} files - Map of filename to content
 * @param {string} symlinkDir - Directory for symlinks
 * @param {object} options - Options
 * @param {boolean} options.force - Force overwrite existing files
 * @param {boolean} options.quiet - Suppress output
 * @returns {Array} - Array of result objects
 */
export function createSymlinks(outputDir, files, symlinkDir, options = {}) {
  const { force = false, quiet = false } = options;

  if (!supportsSymlinks()) {
    if (!quiet) {
      console.log("      Symlinks not supported on Windows");
    }
    return [];
  }

  const resolvedOutputDir = resolvePath(outputDir);
  const resolvedSymlinkDir = ensureSymlinkDir(symlinkDir || DEFAULT_SYMLINK_DIR);
  const results = [];

  const jsFiles = Object.keys(files).filter((f) => f.endsWith(".js"));

  for (const filename of jsFiles) {
    const targetPath = join(resolvedOutputDir, filename);
    const symlinkName = getSymlinkName(filename);
    const linkPath = join(resolvedSymlinkDir, symlinkName);

    const result = createSymlink(targetPath, linkPath, { force });
    results.push({ ...result, filename, symlinkName });

    if (!quiet) {
      if (result.success) {
        const action = result.action === "unchanged" ? "exists" : "linked";
        console.log(`      ${action}: ${symlinkName} -> ${filename}`);
      } else {
        console.warn(`      failed: ${symlinkName} - ${result.error}`);
      }
    }
  }

  return results;
}

/**
 * Get default symlink directory path
 * @returns {string}
 */
export function getDefaultSymlinkDir() {
  return DEFAULT_SYMLINK_DIR;
}

/**
 * Get successful symlink paths
 * @param {Array} results - Array of result objects
 * @returns {Array} - Array of successful symlink paths
 */
export function getSuccessfulSymlinks(results) {
  return results.filter((r) => r.success).map((r) => r.path);
}

export function removeSymlinksForTool(toolPath, symlinkDir = null) {
  const resolvedSymlinkDir = resolvePath(symlinkDir || DEFAULT_SYMLINK_DIR);
  if (!existsSync(resolvedSymlinkDir)) return [];

  const results = [];
  const entries = readdirSync(resolvedSymlinkDir);

  for (const entry of entries) {
    const linkPath = join(resolvedSymlinkDir, entry);
    try {
      const stats = lstatSync(linkPath);
      if (stats.isSymbolicLink()) {
        const target = readlinkSync(linkPath);
        if (dirname(target) === toolPath) {
          unlinkSync(linkPath);
          results.push({ path: linkPath, success: true });
        }
      }
    } catch (error) {
      results.push({ path: linkPath, success: false, error: error.message });
    }
  }
  return results;
}

export function createSymlinksForTool(toolPath, options = {}) {
  const { symlinkDir = DEFAULT_SYMLINK_DIR, force = false, quiet = false } = options;
  const resolvedDir = resolvePath(symlinkDir);
  ensureSymlinkDir(resolvedDir);

  const scripts = readdirSync(toolPath).filter(f => f.endsWith(".js"));
  const files = Object.fromEntries(scripts.map(s => [s, ""]));

  return createSymlinks(toolPath, files, resolvedDir, { force, quiet });
}

/**
 * Agent Registration
 * Handles auto-registration of tools to agent config files (AGENTS.md, CLAUDE.md)
 * Supports idempotent updates via heading-based detection and registry tracking
 */

import { existsSync, readFileSync, writeFileSync, mkdirSync } from "fs";
import { join, dirname } from "path";
import { homedir } from "os";
import { PRESETS, PRESET_PRIORITY } from "./config.js";

const LOCAL_FILE_PRIORITY = ["CLAUDE.md", "AGENTS.md"];
const PRESET_PATHS = new Set(Object.values(PRESETS));
const REGISTRY_DIR = join(homedir(), ".mcp2cli");
const REGISTRY_FILE = join(REGISTRY_DIR, "registry.json");

/**
 * Resolve path, expanding ~ to home directory
 * @param {string} path - Path that may contain ~
 * @returns {string} - Resolved absolute path
 */
export function resolvePath(path) {
  if (path.startsWith("~/")) {
    return join(homedir(), path.slice(2));
  }
  return path;
}

/**
 * Load registry from disk
 * @returns {object} - Registry object with registrations
 */
export function loadRegistry() {
  if (!existsSync(REGISTRY_FILE)) {
    return { registrations: {} };
  }
  try {
    return JSON.parse(readFileSync(REGISTRY_FILE, "utf-8"));
  } catch {
    return { registrations: {} };
  }
}

/**
 * Save registry to disk
 * @param {object} registry - Registry object to save
 */
export function saveRegistry(registry) {
  if (!existsSync(REGISTRY_DIR)) {
    mkdirSync(REGISTRY_DIR, { recursive: true });
  }
  writeFileSync(REGISTRY_FILE, JSON.stringify(registry, null, 2), "utf-8");
}

/**
 * Extract heading from entry content (first ### line)
 * @param {string} content - Entry content
 * @returns {string|null} - Heading line or null
 */
export function extractHeading(content) {
  const match = content.match(/^###\s+.+$/m);
  return match ? match[0] : null;
}

/**
 * Find section by heading in file content
 * Returns boundaries from heading to next ### or EOF
 * @param {string} fileContent - Full file content
 * @param {string} heading - Heading to find (e.g., "### Chrome Devtools Tools")
 * @returns {object|null} - { start, end, content } or null
 */
export function findSectionByHeading(fileContent, heading) {
  const startIndex = fileContent.indexOf(heading);
  if (startIndex === -1) return null;

  const afterHeading = startIndex + heading.length;
  const nextHeadingMatch = fileContent.slice(afterHeading).match(/\n###\s+/);

  let endIndex;
  if (nextHeadingMatch) {
    endIndex = afterHeading + nextHeadingMatch.index;
  } else {
    endIndex = fileContent.length;
  }

  while (endIndex > startIndex && fileContent[endIndex - 1] === "\n") {
    endIndex--;
  }

  return {
    start: startIndex,
    end: endIndex,
    content: fileContent.slice(startIndex, endIndex)
  };
}

/**
 * Detect which agent file to use in local directory
 * Checks for existing CLAUDE.md or AGENTS.md, defaults to AGENTS.md
 * @param {string} cwd - Current working directory
 * @returns {string} - Full path to local agent file
 */
export function detectLocalFile(cwd = process.cwd()) {
  for (const filename of LOCAL_FILE_PRIORITY) {
    const fullPath = join(cwd, filename);
    if (existsSync(fullPath)) {
      return fullPath;
    }
  }
  return join(cwd, "AGENTS.md");
}

/**
 * Register entry to a single target file with idempotent update support
 * @param {string} targetPath - Path to target file (may contain ~)
 * @param {string} entryContent - Content to register
 * @param {string} name - Tool directory name (for registry key)
 * @returns {object} - Result { success, path, action, error? }
 */
export function registerEntry(targetPath, entryContent, name) {
  const resolvedPath = resolvePath(targetPath);
  const heading = extractHeading(entryContent);
  const trimmedContent = entryContent.trim();

  try {
    const dir = dirname(resolvedPath);
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }

    let existingContent = "";
    if (existsSync(resolvedPath)) {
      existingContent = readFileSync(resolvedPath, "utf-8");
    }

    if (heading) {
      const existing = findSectionByHeading(existingContent, heading);

      if (existing) {
        if (existing.content.trim() === trimmedContent) {
          return { success: true, path: targetPath, action: "unchanged" };
        }

        const newContent =
          existingContent.slice(0, existing.start) +
          trimmedContent +
          existingContent.slice(existing.end);

        writeFileSync(resolvedPath, newContent, "utf-8");
        updateRegistry(name, targetPath);
        return { success: true, path: targetPath, action: "updated" };
      }
    }

    let separator = "";
    if (existingContent.length > 0) {
      if (existingContent.endsWith("\n\n")) {
        separator = "";
      } else if (existingContent.endsWith("\n")) {
        separator = "\n";
      } else {
        separator = "\n\n";
      }
    }

    const newContent = existingContent + separator + trimmedContent + "\n";
    writeFileSync(resolvedPath, newContent, "utf-8");

    if (heading) {
      updateRegistry(name, targetPath);
    }

    return { success: true, path: targetPath, action: "created" };
  } catch (error) {
    return { success: false, path: targetPath, action: "error", error: error.message };
  }
}

/**
 * Update registry with custom path registration info
 * Only stores non-preset paths (custom --register-path locations)
 * @param {string} name - Tool directory name
 * @param {string} path - Path where registered
 */
function updateRegistry(name, path) {
  if (PRESET_PATHS.has(path)) {
    return;
  }

  const registry = loadRegistry();

  if (!registry.registrations[name]) {
    registry.registrations[name] = {
      customPaths: [],
      lastUpdated: new Date().toISOString()
    };
  }

  const entry = registry.registrations[name];
  if (!entry.customPaths) {
    entry.customPaths = entry.paths || [];
    delete entry.paths;
    delete entry.heading;
  }
  if (!entry.customPaths.includes(path)) {
    entry.customPaths.push(path);
  }
  entry.lastUpdated = new Date().toISOString();

  saveRegistry(registry);
}

/**
 * Register entry to multiple target files
 * @param {string[]} paths - Array of paths to register to
 * @param {string} entryContent - Content to register
 * @param {string} name - Tool directory name (for registry)
 * @param {object} options - Options
 * @param {boolean} options.quiet - Suppress output
 * @returns {object[]} - Array of results
 */
export function registerToAll(paths, entryContent, name, options = {}) {
  const { quiet = false } = options;
  const results = [];

  for (const path of paths) {
    const result = registerEntry(path, entryContent, name);
    results.push(result);

    if (!quiet) {
      const actionLabels = {
        created: "Registered",
        updated: "Updated",
        unchanged: "Already registered",
        error: "Failed"
      };
      const label = actionLabels[result.action] || "Registered";

      if (result.action === "error") {
        console.warn(`      ${label} ${path}: ${result.error}`);
      } else {
        console.log(`      ${label}: ${path}`);
      }
    }
  }

  return results;
}

/**
 * Resolve all registration paths from effective config
 * Uses fallback chain if no explicit paths specified:
 * - First existing preset in priority order (default)
 * - All existing presets (if allPresets is true)
 * @param {object} effectiveConfig - Merged config with CLI options
 * @returns {string[]} - Array of resolved paths
 */
export function resolveAllPaths(effectiveConfig) {
  const paths = new Set();

  if (effectiveConfig.registerPaths && effectiveConfig.registerPaths.length > 0) {
    for (const p of effectiveConfig.registerPaths) {
      paths.add(p);
    }
  } else if (effectiveConfig.allPresets) {
    for (const presetPath of PRESET_PRIORITY) {
      if (existsSync(resolvePath(presetPath))) {
        paths.add(presetPath);
      }
    }
  } else {
    for (const presetPath of PRESET_PRIORITY) {
      if (existsSync(resolvePath(presetPath))) {
        paths.add(presetPath);
        break;
      }
    }
  }

  if (effectiveConfig.local) {
    const localPath = detectLocalFile();
    paths.add(localPath);
  }

  return Array.from(paths);
}

/**
 * Get successful registration paths for display
 * @param {object[]} results - Results from registerToAll
 * @returns {string[]} - Array of successfully registered paths
 */
export function getSuccessfulPaths(results) {
  return results.filter((r) => r.success).map((r) => r.path);
}

export function unregisterEntry(targetPath, heading) {
  const resolvedPath = resolvePath(targetPath);
  if (!existsSync(resolvedPath)) return { success: true, action: "not_found" };

  try {
    const content = readFileSync(resolvedPath, "utf-8");
    const section = findSectionByHeading(content, heading);
    if (!section) return { success: true, action: "not_found" };

    const newContent = (content.slice(0, section.start) + content.slice(section.end))
      .replace(/\n{3,}/g, "\n\n").trim() + "\n";
    writeFileSync(resolvedPath, newContent, "utf-8");
    return { success: true, action: "removed" };
  } catch (error) {
    return { success: false, action: "error", error: error.message };
  }
}

export function removeFromRegistry(name) {
  const registry = loadRegistry();
  if (registry.registrations[name]) {
    delete registry.registrations[name];
    saveRegistry(registry);
  }
}

/**
 * Output Writer
 * Handles writing generated files to disk or stdout (dry-run)
 * Supports manifest-based tracking for non-destructive updates
 */

import { existsSync, mkdirSync, writeFileSync, chmodSync, rmSync, readFileSync, readdirSync, unlinkSync } from "fs";
import { join, dirname } from "path";
import { homedir } from "os";

const MANIFEST_FILE = ".mcp2cli-manifest.json";
const EXT_MANIFEST_FILE = ".mcp2ext-manifest.json";

/**
 * Resolve output path, expanding ~ to home directory
 * @param {string} path - Path that may contain ~
 * @returns {string} - Resolved absolute path
 */
export function resolvePath(path) {
  if (path.startsWith("~/")) {
    return join(homedir(), path.slice(2));
  }
  return path;
}

/**
 * Check if output directory exists
 * @param {string} outputDir - Output directory path
 * @returns {boolean}
 */
export function outputExists(outputDir) {
  return existsSync(resolvePath(outputDir));
}

/**
 * Read manifest from output directory
 * @param {string} resolvedDir - Resolved output directory path
 * @param {boolean} [isExtension=false] - Whether this is an extension (uses different manifest)
 * @returns {object|null} - Manifest object or null
 */
export function readManifest(resolvedDir, isExtension = false) {
  const manifestFile = isExtension ? EXT_MANIFEST_FILE : MANIFEST_FILE;
  const manifestPath = join(resolvedDir, manifestFile);
  if (!existsSync(manifestPath)) {
    // Try the other manifest file for backwards compatibility
    const altManifestPath = join(resolvedDir, isExtension ? MANIFEST_FILE : EXT_MANIFEST_FILE);
    if (existsSync(altManifestPath)) {
      try {
        return JSON.parse(readFileSync(altManifestPath, "utf-8"));
      } catch {
        return null;
      }
    }
    return null;
  }

  try {
    return JSON.parse(readFileSync(manifestPath, "utf-8"));
  } catch {
    return null;
  }
}

/**
 * Create manifest content for generated files
 * @param {string} packageName - Package name
 * @param {string[]} files - List of generated files
 * @param {boolean} [isExtension=false] - Whether this is an extension
 * @returns {string} - JSON manifest content
 */
export function createManifest(packageName, files, isExtension = false) {
  const manifestFile = isExtension ? EXT_MANIFEST_FILE : MANIFEST_FILE;
  return JSON.stringify({
    version: 1,
    type: isExtension ? "extension" : "cli",
    package: packageName,
    generatedAt: new Date().toISOString(),
    files: files.filter(f => f !== MANIFEST_FILE && f !== EXT_MANIFEST_FILE)
  }, null, 2);
}

/**
 * Get list of user-added files in directory
 * @param {string} resolvedDir - Resolved output directory
 * @param {object} manifest - Existing manifest
 * @returns {string[]} - List of user-added files
 */
export function getUserFiles(resolvedDir, manifest) {
  if (!manifest || !existsSync(resolvedDir)) return [];

  const allFiles = readdirSync(resolvedDir);
  const generatedFiles = new Set([...manifest.files, MANIFEST_FILE, EXT_MANIFEST_FILE]);

  return allFiles.filter(f => !generatedFiles.has(f));
}

/**
 * Write files to output directory
 * @param {string} outputDir - Output directory path
 * @param {object} files - Map of filename to content
 * @param {object} options - Options
 * @param {boolean} options.dryRun - Preview without writing
 * @param {boolean} options.force - Overwrite existing
 * @param {boolean} options.quiet - Suppress output
 * @param {string} options.packageName - Package name for manifest
 * @param {boolean} options.isExtension - Whether this is an extension
 */
export function writeOutput(outputDir, files, options = {}) {
  const { dryRun = false, force = false, quiet = false, packageName = "", isExtension = false } = options;
  const resolvedDir = resolvePath(outputDir);
  const manifestFile = isExtension ? EXT_MANIFEST_FILE : MANIFEST_FILE;

  if (dryRun) {
    console.log("\n--- DRY RUN: Files that would be generated ---\n");

    for (const [filename, content] of Object.entries(files)) {
      console.log(`=== ${filename} ===`);
      console.log(content);
      console.log("");
    }

    console.log(`--- End of dry run (${Object.keys(files).length} files) ---`);
    return;
  }

  if (existsSync(resolvedDir)) {
    if (!force) {
      throw new Error(
        `Output directory exists: ${outputDir}\nUse --force to overwrite`
      );
    }

    const existingManifest = readManifest(resolvedDir, isExtension);

    if (existingManifest) {
      const userFiles = getUserFiles(resolvedDir, existingManifest);
      if (userFiles.length > 0 && !quiet) {
        console.log(`      Preserving ${userFiles.length} user file(s): ${userFiles.join(", ")}`);
      }

      for (const file of existingManifest.files) {
        const filePath = join(resolvedDir, file);
        if (existsSync(filePath)) {
          unlinkSync(filePath);
        }
      }

      // Remove both possible manifest files
      for (const mf of [MANIFEST_FILE, EXT_MANIFEST_FILE]) {
        const manifestPath = join(resolvedDir, mf);
        if (existsSync(manifestPath)) {
          unlinkSync(manifestPath);
        }
      }
    } else {
      if (!quiet) {
        console.log(`      Removing existing: ${outputDir}`);
      }
      rmSync(resolvedDir, { recursive: true });
      mkdirSync(resolvedDir, { recursive: true });
    }
  } else {
    mkdirSync(resolvedDir, { recursive: true });
  }

  for (const [filename, content] of Object.entries(files)) {
    const filePath = join(resolvedDir, filename);

    const parentDir = dirname(filePath);
    if (!existsSync(parentDir)) {
      mkdirSync(parentDir, { recursive: true });
    }

    writeFileSync(filePath, content, "utf-8");

    // Only chmod executable files (.js, .sh) - NOT .ts files
    if (filename.endsWith(".js") || filename.endsWith(".sh")) {
      chmodSync(filePath, 0o755);
    }

    if (!quiet) {
      console.log(`      - ${filename}`);
    }
  }

  const manifestContent = createManifest(packageName, Object.keys(files), isExtension);
  writeFileSync(join(resolvedDir, manifestFile), manifestContent, "utf-8");
}

/**
 * Print success message with next steps (CLI mode)
 * @param {string} outputDir - Output directory path
 * @param {number} toolCount - Number of tools generated
 * @param {string[]} registeredPaths - Paths where tools were registered
 * @param {string|null} symlinkDir - Directory where symlinks were created
 * @param {object} shellConfigResult - Result from shell config (optional)
 */
export function printSuccess(outputDir, toolCount, registeredPaths = [], symlinkDir = null, shellConfigResult = null) {
  const registrationMsg = registeredPaths.length > 0
    ? `Registered in:\n${registeredPaths.map((p) => `  - ${p}`).join("\n")}`
    : "Use --preset or --register-path to register tools.";

  let symlinkMsg = "";
  if (symlinkDir) {
    symlinkMsg = `\nSymlinks created in: ${symlinkDir}`;
    if (shellConfigResult?.action === "added") {
      symlinkMsg += `\nPATH configured in: ${shellConfigResult.configPath}`;
      symlinkMsg += `\nRun: source ${shellConfigResult.configPath}`;
    } else if (shellConfigResult?.action === "exists") {
      symlinkMsg += "\nPATH already configured.";
    } else {
      symlinkMsg += `\nEnsure ${symlinkDir} is in your PATH.`;
    }
  }

  console.log(`
Done! Generated ${toolCount} wrapper scripts in ${outputDir}

${registrationMsg}${symlinkMsg}
`);
}

/**
 * Print success message for extension generation
 * @param {string} outputDir - Output directory path
 * @param {number} toolCount - Number of grouped tools generated
 */
export function printExtensionSuccess(outputDir, toolCount) {
  console.log(`
Done! Generated pi extension with ${toolCount} tool(s) in:
  ${outputDir}

The extension will be auto-discovered by pi on next startup.
No registration required.

To test:
  pi --help  # Should show extension tools

To regenerate from latest MCP schema:
  mcp2ext refresh ${outputDir.split('/').pop()}
`);
}

/**
 * MCP Server Discovery via mcporter
 * Discovers available tools and their schemas from an MCP server
 */

import { exec, execSync } from "child_process";
import { promisify } from "util";
import { buildMcpCommand as buildCommand, fetchPackageDescription, isLocalhost, normalizeHttpUrl, shellEscape } from "./runner.js";

const execAsync = promisify(exec);

/**
 * Derive server name from package name
 * @param {string} packageName - npm package name
 * @returns {string} - server name for mcporter
 */
export function deriveServerName(packageName) {
  // Remove scope, version, and normalize
  // @anthropic-ai/chrome-devtools-mcp@latest -> chrome-devtools
  // chrome-devtools-mcp -> chrome-devtools
  let name = packageName
    .replace(/^@[^/]+\//, "") // Remove scope
    .replace(/@.*$/, "") // Remove version
    .replace(/-mcp$/, "") // Remove -mcp suffix
    .replace(/^mcp-/, ""); // Remove mcp- prefix

  return name;
}

/**
 * Derive output directory name from package name
 * @param {string} packageName - npm package name
 * @returns {string} - directory name
 */
export function deriveDirName(packageName) {
  return deriveServerName(packageName);
}

/**
 * Build the MCP command for execution
 * Delegates to runner module for multi-runner support
 * @param {string} packageName - Package name
 * @param {object} options - Options
 * @param {string} options.command - Explicit command override
 * @param {boolean} options.uvx - Use uvx runner
 * @param {boolean} options.pip - Use pip runner
 * @param {string} options.runner - Runner name override
 * @returns {string} - Command string
 */
export function buildMcpCommand(packageName, options = {}) {
  return buildCommand(packageName, options);
}

/**
 * Check if mcporter is available
 * @returns {boolean}
 */
export function checkMcporter() {
  try {
    execSync("npx mcporter --version", {
      encoding: "utf-8",
      stdio: ["pipe", "pipe", "pipe"],
      timeout: 30000,
    });
    return true;
  } catch {
    return false;
  }
}

/**
 * Try to discover tools with a specific runner
 * @param {string} packageName - Package name
 * @param {string} serverName - Server name
 * @param {object} runnerOptions - Runner options
 * @param {boolean} quiet - Suppress output
 * @returns {Promise<{mcpCommand: string, tools: Array} | null>}
 */
async function tryDiscoverWithRunner(packageName, serverName, runnerOptions, quiet) {
  const mcpCommand = buildMcpCommand(packageName, runnerOptions);
  // Shell-escape serverName for security (defense in depth)
  const cmd = `npx mcporter list --stdio "${mcpCommand}" --name ${shellEscape(serverName)} --schema --json`;
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 60000);

  try {
    const { stdout } = await execAsync(cmd, {
      encoding: "utf-8",
      signal: controller.signal,
      maxBuffer: 10 * 1024 * 1024,
    });

    const data = JSON.parse(stdout);

    if (!data.tools || !Array.isArray(data.tools)) {
      return null;
    }

    return { mcpCommand, tools: data.tools };
  } catch (error) {
    if (error.name === "AbortError") {
      throw new Error("Discovery timed out after 60 seconds");
    }
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
}

/**
 * Try to discover tools from an HTTP endpoint
 * @param {string} httpUrl - HTTP URL to MCP server
 * @param {string} serverName - Server name for mcporter
 * @param {boolean} allowHttp - Allow non-localhost HTTP
 * @param {boolean} quiet - Suppress output
 * @returns {Promise<{tools: Array} | null>}
 */
async function tryDiscoverWithHttp(httpUrl, serverName, allowHttp, quiet) {
  // Normalize URL
  const normalizedUrl = normalizeHttpUrl(httpUrl);

  // Security: non-localhost HTTP requires user's --allow-http consent
  const isLocal = isLocalhost(normalizedUrl);
  const isHttps = normalizedUrl.startsWith("https://");

  if (!isLocal && !isHttps && !allowHttp) {
    throw new Error(
      `Non-localhost HTTP URL requires --allow-http flag for security.\n` +
      `  URL: ${normalizedUrl}\n` +
      `  Use HTTPS or --allow-http to proceed.`
    );
  }

  // mcporter requires --allow-http for ANY http:// URL (even localhost)
  // Only HTTPS doesn't need it
  const needsAllowHttp = !isHttps;
  const allowHttpFlag = needsAllowHttp ? " --allow-http" : "";
  const cmd = `npx mcporter list${allowHttpFlag} --http-url ${shellEscape(normalizedUrl)} --name ${shellEscape(serverName)} --schema --json`;

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 60000);

  try {
    const { stdout } = await execAsync(cmd, {
      encoding: "utf-8",
      signal: controller.signal,
      maxBuffer: 10 * 1024 * 1024,
    });

    const data = JSON.parse(stdout);

    if (!data.tools || !Array.isArray(data.tools)) {
      return null;
    }

    return { tools: data.tools };
  } catch (error) {
    if (error.name === "AbortError") {
      throw new Error("HTTP discovery timed out after 60 seconds");
    }
    // Provide clear error messages for common failures
    if (error.message?.includes("ECONNREFUSED")) {
      throw new Error(`Connection refused to ${normalizedUrl}. Is the MCP server running?`);
    }
    if (error.message?.includes("ETIMEDOUT") || error.message?.includes("ENOTFOUND")) {
      throw new Error(`Could not reach ${normalizedUrl}. Check the URL and network connection.`);
    }
    if (error.stderr?.includes("HTTP") && error.stderr?.includes("rejected")) {
      throw new Error(`HTTP request rejected by server at ${normalizedUrl}`);
    }
    // Re-throw with context if it's an unexpected error
    if (error.stderr) {
      throw new Error(`HTTP discovery failed: ${error.stderr.trim()}`);
    }
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
}

/**
 * Discover tools from an MCP server
 * Supports npm (npx), Python (uvx), pip runners, and HTTP endpoints
 * Fetches package description in parallel with discovery (zero added latency)
 * @param {string} packageName - Package name (or server name for HTTP mode)
 * @param {object} options - options
 * @param {boolean} options.quiet - suppress progress output
 * @param {boolean} options.uvx - Use uvx runner (Python)
 * @param {boolean} options.pip - Use pip runner (python -m)
 * @param {string} options.command - Explicit command override
 * @param {string} options.httpUrl - HTTP URL for MCP endpoint
 * @param {string} options.description - User-provided description (for HTTP mode)
 * @param {boolean} options.allowHttp - Allow non-localhost HTTP URLs
 * @returns {Promise<{serverName: string, mcpCommand?: string, httpUrl?: string, allowHttp?: boolean, tools: Array<{name: string, description?: string, inputSchema?: object}>, runner: string, description: string|undefined}>}
 */
export async function discoverTools(packageName, options = {}) {
  const { quiet = false, uvx, pip, command, httpUrl, description, allowHttp } = options;

  // HTTP mode
  if (httpUrl) {
    const serverName = deriveServerName(packageName);
    const normalizedUrl = normalizeHttpUrl(httpUrl);
    const isHttps = normalizedUrl.startsWith("https://");

    if (!quiet) {
      console.log(`      Server name: ${serverName}`);
      console.log(`      HTTP URL: ${normalizedUrl}`);
    }

    const result = await tryDiscoverWithHttp(normalizedUrl, serverName, allowHttp, quiet);
    if (!result) {
      throw new Error(`HTTP discovery failed for ${normalizedUrl}`);
    }

    // allowHttp in return = whether generated code needs --allow-http flag
    // mcporter needs it for any http:// URL (not https://)
    return {
      serverName,
      httpUrl: normalizedUrl,
      allowHttp: !isHttps,
      tools: result.tools,
      runner: "http",
      description,
    };
  }

  const serverName = deriveServerName(packageName);

  if (command) {
    const mcpCommand = command;
    if (!quiet) {
      console.log(`      Server name: ${serverName}`);
      console.log(`      MCP command: ${mcpCommand} (custom)`);
    }

    const result = await tryDiscoverWithRunner(packageName, serverName, { command }, quiet);
    if (!result) {
      throw new Error(`Discovery failed with custom command: ${command}`);
    }

    return { serverName, mcpCommand, tools: result.tools, runner: "custom", description: undefined };
  }

  if (uvx) {
    const mcpCommand = buildMcpCommand(packageName, { uvx: true });
    if (!quiet) {
      console.log(`      Server name: ${serverName}`);
      console.log(`      MCP command: ${mcpCommand}`);
    }

    const [result, description] = await Promise.all([
      tryDiscoverWithRunner(packageName, serverName, { uvx: true }, quiet),
      fetchPackageDescription(packageName, "uvx"),
    ]);
    if (!result) {
      throw new Error(`Discovery failed with uvx. Is the package available on PyPI?`);
    }

    return { serverName, mcpCommand, tools: result.tools, runner: "uvx", description };
  }

  if (pip) {
    const mcpCommand = buildMcpCommand(packageName, { pip: true });
    if (!quiet) {
      console.log(`      Server name: ${serverName}`);
      console.log(`      MCP command: ${mcpCommand}`);
    }

    const [result, description] = await Promise.all([
      tryDiscoverWithRunner(packageName, serverName, { pip: true }, quiet),
      fetchPackageDescription(packageName, "pip"),
    ]);
    if (!result) {
      throw new Error(`Discovery failed with pip. Is the package installed via pip?`);
    }

    return { serverName, mcpCommand, tools: result.tools, runner: "pip", description };
  }

  if (!quiet) {
    console.log(`      Server name: ${serverName}`);
  }

  const npxCommand = buildMcpCommand(packageName, { runner: "npx" });
  if (!quiet) {
    console.log(`      Trying npm: ${npxCommand}`);
  }

  const [npxResult, npmDescription] = await Promise.all([
    tryDiscoverWithRunner(packageName, serverName, { runner: "npx" }, quiet),
    fetchPackageDescription(packageName, "npx"),
  ]);
  if (npxResult) {
    return { serverName, mcpCommand: npxCommand, tools: npxResult.tools, runner: "npx", description: npmDescription };
  }

  if (!quiet) {
    console.log(`      npm: not found, trying uvx...`);
  }

  const uvxCommand = buildMcpCommand(packageName, { runner: "uvx" });
  const [uvxResult, pypiDescription] = await Promise.all([
    tryDiscoverWithRunner(packageName, serverName, { runner: "uvx" }, quiet),
    fetchPackageDescription(packageName, "uvx"),
  ]);
  if (uvxResult) {
    if (!quiet) {
      console.log(`      uvx: found ${uvxResult.tools.length} tools`);
    }
    return { serverName, mcpCommand: uvxCommand, tools: uvxResult.tools, runner: "uvx", description: pypiDescription };
  }

  throw new Error(
    `Package "${packageName}" not found on npm or PyPI.\n` +
    `  For npm packages, check the package name is correct.\n` +
    `  For Python packages, use: --uvx flag\n` +
    `  For pip-installed packages, use: --pip flag`
  );
}

/**
 * Runner Module
 * Handles package runner detection and command building for npm (npx), Python (uvx), and pip
 * Also provides security utilities for HTTP endpoint support
 */

/**
 * Check if a string is a valid HTTP or HTTPS URL
 * @param {string} url - URL to check
 * @returns {boolean} - true if http:// or https://
 */
export function isHttpUrl(url) {
  if (!url || typeof url !== "string") return false;
  try {
    const parsed = new URL(url);
    return parsed.protocol === "http:" || parsed.protocol === "https:";
  } catch {
    return false;
  }
}

/**
 * Check if a URL points to localhost
 * Identifies 127.x.x.x, localhost, ::1
 * Rejects spoofed hostnames like localhost.evil.com
 * @param {string} url - URL to check
 * @returns {boolean} - true if localhost
 */
export function isLocalhost(url) {
  if (!url || typeof url !== "string") return false;
  try {
    const parsed = new URL(url);
    const hostname = parsed.hostname.toLowerCase();

    if (hostname === "localhost") return true;
    if (hostname === "::1" || hostname === "[::1]") return true;

    if (/^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(hostname)) {
      const parts = hostname.split(".").map(Number);
      return parts.every((p) => p >= 0 && p <= 255);
    }

    return false;
  } catch {
    return false;
  }
}

/**
 * Normalize an HTTP URL
 * Removes trailing slashes, validates scheme
 * @param {string} url - URL to normalize
 * @returns {string} - Normalized URL
 * @throws {Error} - If URL is invalid or not HTTP/HTTPS
 */
export function normalizeHttpUrl(url) {
  if (!isHttpUrl(url)) {
    throw new Error(`Invalid HTTP URL: ${url}`);
  }
  return url.replace(/\/+$/, "");
}

/**
 * Shell escape a string for safe use in shell commands
 * Wraps in single quotes and escapes internal single quotes
 * @param {string} str - String to escape
 * @returns {string} - Shell-safe string
 */
export function shellEscape(str) {
  if (str === undefined || str === null) return "''";
  return "'" + String(str).replace(/'/g, "'\\''") + "'";
}

/**
 * Validate a server name for safe use
 * Rejects shell metacharacters and dangerous patterns
 * @param {string} name - Server name to validate
 * @returns {boolean} - true if safe
 */
export function isValidServerName(name) {
  if (!name || typeof name !== "string") return false;
  if (name.length === 0 || name.length > 128) return false;
  return /^[a-zA-Z0-9_-]+$/.test(name);
}

/**
 * Escape a string for use in JavaScript template literals
 * Escapes backticks, ${}, and backslashes
 * @param {string} str - String to escape
 * @returns {string} - Escaped string
 */
export function escapeTemplateLiteral(str) {
  if (str === undefined || str === null) return "";
  return String(str)
    .replace(/\\/g, "\\\\")
    .replace(/`/g, "\\`")
    .replace(/\$\{/g, "\\${");
}

/**
 * Escape a string for use in double-quoted strings
 * Escapes quotes, backslashes, and newlines
 * @param {string} str - String to escape
 * @returns {string} - Escaped string
 */
export function escapeDoubleQuotedString(str) {
  if (str === undefined || str === null) return "";
  return String(str)
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"')
    .replace(/\n/g, "\\n")
    .replace(/\r/g, "\\r");
}

/**
 * Convert package name to Python module name
 * mcp-server-fetch -> mcp_server_fetch
 * @param {string} pkg - Package name
 * @returns {string} - Module name
 */
export function toModuleName(pkg) {
  return pkg.replace(/-/g, "_");
}

/**
 * Runner configurations
 */
export const RUNNERS = {
  npx: {
    cmd: "npx",
    args: ["-y"],
    suffix: "@latest",
    transform: null,
  },
  uvx: {
    cmd: "uvx",
    args: [],
    suffix: "",
    transform: null,
  },
  pip: {
    cmd: "python",
    args: ["-m"],
    suffix: "",
    transform: toModuleName,
  },
};

/**
 * Determine runner based on options
 * @param {object} options - Options
 * @param {boolean} options.uvx - Use uvx runner
 * @param {boolean} options.pip - Use pip runner (python -m)
 * @returns {string} - Runner name
 */
export function detectRunner(options = {}) {
  if (options.uvx) return "uvx";
  if (options.pip) return "pip";
  return "npx";
}

/**
 * Build the MCP command for execution
 * @param {string} packageName - Package name
 * @param {object} options - Options
 * @param {string} options.command - Explicit command override (bypasses everything)
 * @param {boolean} options.uvx - Use uvx runner
 * @param {boolean} options.pip - Use pip runner (python -m)
 * @param {string} options.runner - Runner name override (internal use)
 * @returns {string} - Full command string
 */
export function buildMcpCommand(packageName, options = {}) {
  if (options.command) {
    return options.command;
  }

  const runnerName = options.runner || detectRunner(options);
  const runner = RUNNERS[runnerName];

  if (!runner) {
    throw new Error(`Unknown runner: ${runnerName}`);
  }

  let pkg = packageName;

  if (runner.transform) {
    pkg = runner.transform(pkg);
  }

  if (runner.suffix) {
    const hasVersion = pkg.includes("@") && (!pkg.startsWith("@") || pkg.slice(1).includes("@"));
    if (!hasVersion) {
      pkg = `${pkg}${runner.suffix}`;
    }
  }

  const parts = [runner.cmd, ...runner.args, pkg];
  return parts.join(" ");
}

/**
 * Get list of available runner names
 * @returns {string[]}
 */
export function getRunnerNames() {
  return Object.keys(RUNNERS);
}

/**
 * Extract package name without version suffix
 * Keeps scope for npm packages: @scope/pkg@1.0.0 -> @scope/pkg
 * @param {string} packageName - Package name with optional version
 * @returns {string} - Package name without version
 */
export function stripVersion(packageName) {
  if (packageName.startsWith("@")) {
    const slashIndex = packageName.indexOf("/");
    if (slashIndex !== -1) {
      const afterSlash = packageName.slice(slashIndex + 1);
      const versionIndex = afterSlash.indexOf("@");
      if (versionIndex !== -1) {
        return packageName.slice(0, slashIndex + 1 + versionIndex);
      }
    }
    return packageName;
  }
  return packageName.replace(/@.*$/, "");
}

/**
 * Extract the first paragraph from a README (after the title)
 * Skips headings, badges, and empty lines
 * @param {string} readme - README content
 * @returns {string|undefined} - First paragraph or undefined
 */
export function extractFirstParagraph(readme) {
  if (!readme) return undefined;
  const lines = readme.split("\n");
  let inParagraph = false;
  let paragraph = "";

  for (const line of lines) {
    const trimmed = line.trim();

    if (!inParagraph) {
      if (trimmed === "" || trimmed.startsWith("#") || trimmed.startsWith("[![") || trimmed.startsWith("![")) {
        continue;
      }
      inParagraph = true;
    }

    if (inParagraph && (trimmed === "" || trimmed.startsWith("#"))) {
      break;
    }

    paragraph += (paragraph ? " " : "") + trimmed;
  }

  return paragraph || undefined;
}

/**
 * Fetch package description from npm registry
 * Prefers first README paragraph over short description field
 * @param {string} packageName - Package name
 * @returns {Promise<string|undefined>}
 */
async function fetchNpmDescription(packageName) {
  try {
    const pkgName = stripVersion(packageName);
    const encodedName = pkgName.replace("/", "%2f");
    const response = await fetch(`https://registry.npmjs.org/${encodedName}`, {
      signal: AbortSignal.timeout(5000),
    });
    if (!response.ok) return undefined;
    const data = await response.json();

    if (data.readme) {
      const paragraph = extractFirstParagraph(data.readme);
      if (paragraph && paragraph.length > 20) {
        return paragraph;
      }
    }

    return data.description;
  } catch {
    return undefined;
  }
}

/**
 * Fetch package description from PyPI
 * Prefers first README paragraph over short summary field
 * @param {string} packageName - Package name
 * @returns {Promise<string|undefined>}
 */
async function fetchPyPIDescription(packageName) {
  try {
    const pkgName = stripVersion(packageName);
    const response = await fetch(`https://pypi.org/pypi/${pkgName}/json`, {
      signal: AbortSignal.timeout(5000),
    });
    if (!response.ok) return undefined;
    const data = await response.json();

    if (data.info?.description) {
      const paragraph = extractFirstParagraph(data.info.description);
      if (paragraph && paragraph.length > 20) {
        return paragraph;
      }
    }

    return data.info?.summary;
  } catch {
    return undefined;
  }
}

/**
 * Fetch package description from the appropriate registry
 * @param {string} packageName - Package name
 * @param {string} runner - Runner type: "npx", "uvx", "pip", or "custom"
 * @returns {Promise<string|undefined>}
 */
export async function fetchPackageDescription(packageName, runner) {
  switch (runner) {
    case "npx":
      return fetchNpmDescription(packageName);
    case "uvx":
    case "pip":
      return fetchPyPIDescription(packageName);
    default:
      return undefined;
  }
}

/**
 * JSON Schema to TypeBox Converter
 * Converts MCP JSON Schema to TypeBox code strings for pi extensions
 */

/**
 * Convert a JSON Schema type to TypeBox code
 * @param {object} schema - JSON Schema object
 * @param {boolean} [isOptional=false] - Whether this property is optional
 * @returns {string} - TypeBox code string
 */
export function schemaToTypeBox(schema, isOptional = false) {
  if (!schema || typeof schema !== "object") {
    const type = "Type.Unknown()";
    return isOptional ? `Type.Optional(${type})` : type;
  }

  const opts = buildOptions(schema);
  let typeBox;

  // Handle enum first (can combine with type)
  if (schema.enum && Array.isArray(schema.enum)) {
    typeBox = buildEnumType(schema.enum, opts);
  } else if (schema.type === "string") {
    typeBox = opts ? `Type.String(${opts})` : "Type.String()";
  } else if (schema.type === "number") {
    typeBox = opts ? `Type.Number(${opts})` : "Type.Number()";
  } else if (schema.type === "integer") {
    typeBox = opts ? `Type.Integer(${opts})` : "Type.Integer()";
  } else if (schema.type === "boolean") {
    typeBox = opts ? `Type.Boolean(${opts})` : "Type.Boolean()";
  } else if (schema.type === "null") {
    typeBox = opts ? `Type.Null(${opts})` : "Type.Null()";
  } else if (schema.type === "array") {
    typeBox = buildArrayType(schema, opts);
  } else if (schema.type === "object" || schema.properties) {
    typeBox = buildObjectType(schema, opts);
  } else if (Array.isArray(schema.type)) {
    // Union type (e.g., ["string", "null"])
    typeBox = buildUnionType(schema, opts);
  } else if (schema.oneOf || schema.anyOf) {
    typeBox = buildUnionFromSchemas(schema.oneOf || schema.anyOf, opts);
  } else if (schema.allOf) {
    typeBox = buildIntersectionType(schema.allOf, opts);
  } else {
    // Fallback for unknown types
    typeBox = opts ? `Type.Unknown(${opts})` : "Type.Unknown()";
  }

  return isOptional ? `Type.Optional(${typeBox})` : typeBox;
}

/**
 * Build TypeBox options object from JSON Schema
 * @param {object} schema - JSON Schema object
 * @returns {string|null} - Options object string or null
 */
function buildOptions(schema) {
  const opts = {};

  if (schema.description) {
    opts.description = schema.description;
  }
  if (schema.default !== undefined) {
    opts.default = schema.default;
  }
  if (schema.minimum !== undefined) {
    opts.minimum = schema.minimum;
  }
  if (schema.maximum !== undefined) {
    opts.maximum = schema.maximum;
  }
  if (schema.minLength !== undefined) {
    opts.minLength = schema.minLength;
  }
  if (schema.maxLength !== undefined) {
    opts.maxLength = schema.maxLength;
  }
  if (schema.pattern !== undefined) {
    opts.pattern = schema.pattern;
  }
  if (schema.minItems !== undefined) {
    opts.minItems = schema.minItems;
  }
  if (schema.maxItems !== undefined) {
    opts.maxItems = schema.maxItems;
  }

  const keys = Object.keys(opts);
  if (keys.length === 0) {
    return null;
  }

  // Build options object string
  const parts = keys.map((key) => {
    const value = opts[key];
    if (typeof value === "string") {
      // Escape quotes and special characters in strings
      return `${key}: "${escapeStringLiteral(value)}"`;
    }
    return `${key}: ${JSON.stringify(value)}`;
  });

  return `{ ${parts.join(", ")} }`;
}

/**
 * Escape a string for use in a TypeScript string literal
 * @param {string} str - String to escape
 * @returns {string} - Escaped string (without surrounding quotes)
 */
function escapeStringLiteral(str) {
  return str
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"')
    .replace(/\n/g, "\\n")
    .replace(/\r/g, "\\r")
    .replace(/\t/g, "\\t");
}

/**
 * Build enum type using StringEnum helper
 * @param {Array} enumValues - Array of enum values
 * @param {string|null} opts - Options string
 * @returns {string} - TypeBox code string
 */
function buildEnumType(enumValues, opts) {
  // Check if all values are strings
  const allStrings = enumValues.every((v) => typeof v === "string");

  if (allStrings) {
    const values = enumValues.map((v) => `"${escapeStringLiteral(v)}"`).join(", ");
    if (opts) {
      return `StringEnum([${values}] as const, ${opts})`;
    }
    return `StringEnum([${values}] as const)`;
  }

  // Mixed types - use Type.Union with Type.Literal
  const literals = enumValues.map((v) => {
    if (typeof v === "string") {
      return `Type.Literal("${escapeStringLiteral(v)}")`;
    }
    return `Type.Literal(${JSON.stringify(v)})`;
  });

  const union = `Type.Union([${literals.join(", ")}])`;
  // Note: Union doesn't take options directly
  return union;
}

/**
 * Build array type
 * @param {object} schema - JSON Schema with type: "array"
 * @param {string|null} opts - Options string
 * @returns {string} - TypeBox code string
 */
function buildArrayType(schema, opts) {
  let itemsType;

  if (schema.items) {
    itemsType = schemaToTypeBox(schema.items, false);
  } else {
    itemsType = "Type.Unknown()";
  }

  if (opts) {
    return `Type.Array(${itemsType}, ${opts})`;
  }
  return `Type.Array(${itemsType})`;
}

/**
 * Build object type
 * @param {object} schema - JSON Schema with type: "object" or properties
 * @param {string|null} opts - Options string
 * @returns {string} - TypeBox code string
 */
function buildObjectType(schema, opts) {
  if (!schema.properties || Object.keys(schema.properties).length === 0) {
    // Empty object or additionalProperties only
    if (schema.additionalProperties) {
      const valueType = schemaToTypeBox(schema.additionalProperties, false);
      if (opts) {
        return `Type.Record(Type.String(), ${valueType}, ${opts})`;
      }
      return `Type.Record(Type.String(), ${valueType})`;
    }
    if (opts) {
      return `Type.Object({}, ${opts})`;
    }
    return "Type.Object({})";
  }

  const required = new Set(schema.required || []);
  const props = [];

  for (const [propName, propSchema] of Object.entries(schema.properties)) {
    const isOptional = !required.has(propName);
    const propType = schemaToTypeBox(propSchema, isOptional);
    // Use computed property name if propName has special characters
    if (/^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(propName)) {
      props.push(`${propName}: ${propType}`);
    } else {
      props.push(`"${escapeStringLiteral(propName)}": ${propType}`);
    }
  }

  const propsStr = props.join(",\n    ");

  if (opts) {
    return `Type.Object({\n    ${propsStr},\n  }, ${opts})`;
  }
  return `Type.Object({\n    ${propsStr},\n  })`;
}

/**
 * Build union type from array of type names
 * @param {object} schema - Schema with array type field
 * @param {string|null} opts - Options string
 * @returns {string} - TypeBox code string
 */
function buildUnionType(schema, opts) {
  const types = schema.type.map((t) => {
    if (t === "string") return "Type.String()";
    if (t === "number") return "Type.Number()";
    if (t === "integer") return "Type.Integer()";
    if (t === "boolean") return "Type.Boolean()";
    if (t === "null") return "Type.Null()";
    if (t === "array") return buildArrayType(schema);
    if (t === "object") return buildObjectType(schema);
    return "Type.Unknown()";
  });

  return `Type.Union([${types.join(", ")}])`;
}

/**
 * Build union from oneOf/anyOf schemas
 * @param {Array} schemas - Array of schemas
 * @param {string|null} opts - Options string
 * @returns {string} - TypeBox code string
 */
function buildUnionFromSchemas(schemas, opts) {
  const types = schemas.map((s) => schemaToTypeBox(s, false));
  return `Type.Union([${types.join(", ")}])`;
}

/**
 * Build intersection from allOf schemas
 * @param {Array} schemas - Array of schemas
 * @param {string|null} opts - Options string
 * @returns {string} - TypeBox code string
 */
function buildIntersectionType(schemas, opts) {
  const types = schemas.map((s) => schemaToTypeBox(s, false));
  return `Type.Intersect([${types.join(", ")}])`;
}

/**
 * Convert parameter name from snake_case or kebab-case to camelCase
 * @param {string} name - Parameter name in snake_case or kebab-case
 * @returns {string} - Parameter name in camelCase
 */
export function snakeToCamel(name) {
  return name.replace(/[-_]([a-z])/g, (_, letter) => letter.toUpperCase());
}

/**
 * Convert parameter name from camelCase to snake_case
 * @param {string} name - Parameter name in camelCase
 * @returns {string} - Parameter name in snake_case
 */
export function camelToSnake(name) {
  return name.replace(/([A-Z])/g, "_$1").toLowerCase();
}

/**
 * Generate TypeBox schema for a complete MCP tool
 * @param {object} tool - MCP tool with inputSchema
 * @returns {string} - TypeBox Type.Object code string
 */
export function toolSchemaToTypeBox(tool) {
  if (!tool.inputSchema || !tool.inputSchema.properties) {
    return "Type.Object({})";
  }

  return schemaToTypeBox(tool.inputSchema, false);
}

/**
 * Merge multiple MCP tool schemas into a single grouped schema
 * @param {Array} tools - Array of MCP tools with inputSchema
 * @param {string} actionParamName - Name for the action discriminator param (default: "action")
 * @returns {object} - { schema: string, actionValues: string[], paramMapping: object }
 */
export function mergeToolSchemas(tools, actionParamName = "action") {
  if (tools.length === 0) {
    return {
      schema: "Type.Object({})",
      actionValues: [],
      paramMapping: {},
    };
  }

  if (tools.length === 1) {
    const tool = tools[0];
    return {
      schema: toolSchemaToTypeBox(tool),
      actionValues: [tool.name],
      paramMapping: buildParamMapping(tool),
    };
  }

  const actionValues = tools.map((t) => t.name);

  // Collect all parameters from all tools
  const allParams = new Map(); // camelName -> { schema, tools: Set, required: Set }

  for (const tool of tools) {
    const props = tool.inputSchema?.properties || {};
    const required = new Set(tool.inputSchema?.required || []);

    for (const [snakeName, paramSchema] of Object.entries(props)) {
      const camelName = snakeToCamel(snakeName);

      if (!allParams.has(camelName)) {
        allParams.set(camelName, {
          snakeName,
          schema: paramSchema,
          tools: new Set(),
          required: new Set(),
        });
      }

      const entry = allParams.get(camelName);
      entry.tools.add(tool.name);
      if (required.has(snakeName)) {
        entry.required.add(tool.name);
      }
    }
  }

  // Build merged schema
  const props = [];
  const paramMapping = {};

  // Add action parameter first
  const actionEnumValues = actionValues.map((v) => `"${escapeStringLiteral(v)}"`).join(", ");
  props.push(
    `${actionParamName}: StringEnum([${actionEnumValues}] as const, { description: "Action to perform" })`
  );

  // Add merged parameters
  for (const [camelName, entry] of allParams) {
    paramMapping[camelName] = entry.snakeName;

    // Parameter is required only if it's required in ALL tools that use it
    // and ALL tools use this parameter
    const isRequiredInAll =
      entry.required.size === tools.length &&
      entry.tools.size === tools.length;

    // Build description noting which actions use this param
    let description = entry.schema.description || "";
    if (entry.tools.size < tools.length) {
      const toolList = Array.from(entry.tools).join(", ");
      const actionNote = `Only for: ${toolList}`;
      description = description ? `${description}. ${actionNote}` : actionNote;
    }

    // Clone schema with updated description
    const enhancedSchema = {
      ...entry.schema,
      description: description || undefined,
    };

    const typeBoxCode = schemaToTypeBox(enhancedSchema, !isRequiredInAll);
    props.push(`${camelName}: ${typeBoxCode}`);
  }

  const propsStr = props.join(",\n    ");
  const schema = `Type.Object({\n    ${propsStr},\n  })`;

  return {
    schema,
    actionValues,
    paramMapping,
  };
}

/**
 * Build parameter name mapping for a single tool
 * @param {object} tool - MCP tool
 * @returns {object} - Map of camelCase to snake_case names
 */
function buildParamMapping(tool) {
  const mapping = {};
  const props = tool.inputSchema?.properties || {};

  for (const snakeName of Object.keys(props)) {
    const camelName = snakeToCamel(snakeName);
    mapping[camelName] = snakeName;
  }

  return mapping;
}

/**
 * Check if a parameter name is a valid TypeScript identifier
 * @param {string} name - Parameter name
 * @returns {boolean}
 */
export function isValidIdentifier(name) {
  return /^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(name);
}

/**
 * Check if a name is a valid tool name (snake_case)
 * @param {string} name - Tool name
 * @returns {boolean}
 */
export function isValidToolName(name) {
  return /^[a-z][a-z0-9_]*$/.test(name);
}

/**
 * Migration Tooling
 * Migrates existing ~/agent-tools/ CLI tools to pi extensions
 */

import { readdirSync, statSync, existsSync, readFileSync, rmSync } from "fs";
import { join } from "path";
import { homedir } from "os";
import { generateExtensionFiles } from "./extension-generator.js";
import { discoverTools } from "./discovery.js";
import { groupToolsForExtension, fallbackGroupingForExtension } from "./grouping.js";
import { writeOutput } from "./output.js";
import { removeTool } from "./management.js";

const AGENT_TOOLS_DIR = join(homedir(), "agent-tools");
const EXTENSIONS_DIR = join(homedir(), ".pi", "agent", "extensions");

/**
 * Pattern to extract MCP command from CLI scripts
 * Looks for: const MCP_CMD = "..." or MCP_CMD = "..."
 */
const MCP_CMD_PATTERN = /(?:const\s+)?MCP_CMD\s*=\s*["'`]([^"'`]+)["'`]/;

/**
 * Pattern to extract mcporter call command
 * Looks for: mcporter call --stdio "..." server.tool
 */
const MCPORTER_CALL_PATTERN = /mcporter\s+call\s+--stdio\s+["'`]([^"'`]+)["'`]\s+([a-zA-Z0-9_-]+)\./;

/**
 * Scan a CLI script and extract MCP command
 * @param {string} scriptPath - Path to the script file
 * @returns {string|null} - MCP command or null if not found
 */
export function extractMcpCommand(scriptPath) {
  if (!existsSync(scriptPath)) return null;

  try {
    const content = readFileSync(scriptPath, "utf-8");

    // Try MCP_CMD pattern first
    const mcpCmdMatch = content.match(MCP_CMD_PATTERN);
    if (mcpCmdMatch) {
      return mcpCmdMatch[1];
    }

    // Try mcporter call pattern
    const mcporterMatch = content.match(MCPORTER_CALL_PATTERN);
    if (mcporterMatch) {
      return mcporterMatch[1];
    }

    return null;
  } catch {
    return null;
  }
}

/**
 * Extract server name from CLI scripts
 * Looks for: const SERVER = "..."
 * @param {string} scriptPath - Path to the script file
 * @returns {string|null} - Server name or null
 */
export function extractServerName(scriptPath) {
  if (!existsSync(scriptPath)) return null;

  try {
    const content = readFileSync(scriptPath, "utf-8");

    // Look for SERVER constant
    const serverMatch = content.match(/(?:const\s+)?SERVER\s*=\s*["'`]([^"'`]+)["'`]/);
    if (serverMatch) {
      return serverMatch[1];
    }

    // Try to extract from mcporter call
    const mcporterMatch = content.match(MCPORTER_CALL_PATTERN);
    if (mcporterMatch) {
      return mcporterMatch[2];
    }

    return null;
  } catch {
    return null;
  }
}

/**
 * Scan ~/agent-tools/ for migrateable CLI tools
 * @returns {Array} - Array of tool info objects
 */
export function scanCliTools() {
  if (!existsSync(AGENT_TOOLS_DIR)) {
    return [];
  }

  const entries = readdirSync(AGENT_TOOLS_DIR);
  const tools = [];

  for (const entry of entries) {
    if (entry === "bin") continue;

    const toolPath = join(AGENT_TOOLS_DIR, entry);

    try {
      if (!statSync(toolPath).isDirectory()) continue;

      // Find JS scripts
      const scripts = readdirSync(toolPath)
        .filter((f) => f.endsWith(".js") && !f.startsWith("."));

      if (scripts.length === 0) continue;

      // Try to extract MCP command from first script
      let mcpCommand = null;
      let serverName = null;

      for (const script of scripts) {
        const scriptPath = join(toolPath, script);
        mcpCommand = extractMcpCommand(scriptPath);
        serverName = extractServerName(scriptPath);
        if (mcpCommand) break;
      }

      // Read package.json for description
      let description = null;
      const pkgPath = join(toolPath, "package.json");
      if (existsSync(pkgPath)) {
        try {
          const pkg = JSON.parse(readFileSync(pkgPath, "utf-8"));
          description = pkg.description;
        } catch {
          // Ignore parse errors
        }
      }

      tools.push({
        name: entry,
        path: toolPath,
        scripts,
        mcpCommand,
        serverName,
        description,
        canMigrate: !!mcpCommand,
      });
    } catch {
      continue;
    }
  }

  return tools;
}

/**
 * Derive package name from MCP command
 * @param {string} mcpCommand - MCP command string
 * @returns {string} - Package name
 */
export function derivePackageName(mcpCommand) {
  if (!mcpCommand) return "unknown";

  // Extract package from npx command: npx -y <package>@latest
  // Handle scoped packages like @anthropic-ai/chrome-devtools-mcp@latest
  const npxScopedMatch = mcpCommand.match(/npx\s+(?:-y\s+)?(@[^@\s]+\/[^@\s]+)(?:@[^\s]+)?/);
  if (npxScopedMatch) {
    return npxScopedMatch[1];
  }

  // Handle unscoped packages
  const npxMatch = mcpCommand.match(/npx\s+(?:-y\s+)?([^@\s]+)(?:@[^\s]+)?/);
  if (npxMatch) {
    return npxMatch[1];
  }

  // Extract package from uvx command: uvx <package>
  const uvxMatch = mcpCommand.match(/uvx\s+([^\s]+)/);
  if (uvxMatch) {
    return uvxMatch[1];
  }

  // Extract package from docker command: docker run ... <image>
  const dockerMatch = mcpCommand.match(/docker\s+run\s+.*?\s+([^\s]+)$/);
  if (dockerMatch) {
    return dockerMatch[1];
  }

  // Return last word as fallback
  const parts = mcpCommand.trim().split(/\s+/);
  return parts[parts.length - 1];
}

/**
 * Determine runner type from MCP command
 * @param {string} mcpCommand - MCP command string
 * @returns {"npx" | "uvx" | "pip" | "docker" | "custom"} - Runner type
 */
export function deriveRunnerType(mcpCommand) {
  if (!mcpCommand) return "custom";

  if (mcpCommand.startsWith("npx ")) return "npx";
  if (mcpCommand.startsWith("uvx ")) return "uvx";
  if (mcpCommand.includes("pip ")) return "pip";
  if (mcpCommand.includes("docker ")) return "docker";

  return "custom";
}

/**
 * Migrate a single CLI tool to pi extension
 * @param {string} name - Tool name
 * @param {object} options - Options
 * @param {boolean} options.dryRun - Preview without writing
 * @param {boolean} options.quiet - Suppress output
 * @param {boolean} options.cleanup - Remove old CLI tool after migration
 * @param {boolean} options.force - Overwrite existing extension
 * @param {string} options.agentType - AI agent type for grouping
 * @returns {object} - Result object
 */
export async function migrateTool(name, options = {}) {
  const { dryRun = false, quiet = false, cleanup = false, force = false, agentType = null } = options;

  // Find the tool
  const toolPath = join(AGENT_TOOLS_DIR, name);
  if (!existsSync(toolPath) || !statSync(toolPath).isDirectory()) {
    return { success: false, error: `Tool "${name}" not found in ~/agent-tools/` };
  }

  // Extract MCP command from scripts
  const scripts = readdirSync(toolPath).filter((f) => f.endsWith(".js") && !f.startsWith("."));
  if (scripts.length === 0) {
    return { success: false, error: `No scripts found in ~/agent-tools/${name}/` };
  }

  let mcpCommand = null;
  let serverName = null;
  for (const script of scripts) {
    const scriptPath = join(toolPath, script);
    mcpCommand = extractMcpCommand(scriptPath);
    serverName = extractServerName(scriptPath);
    if (mcpCommand) break;
  }

  if (!mcpCommand) {
    return { success: false, error: `Could not extract MCP command from scripts in ~/agent-tools/${name}/` };
  }

  // Check if extension already exists
  const extPath = join(EXTENSIONS_DIR, name);
  if (existsSync(extPath) && !force && !dryRun) {
    return { success: false, error: `Extension "${name}" already exists. Use --force to overwrite.` };
  }

  // Derive package name and runner type
  const packageName = derivePackageName(mcpCommand);
  const runnerType = deriveRunnerType(mcpCommand);

  if (!quiet) {
    console.log(`Migrating: ${name}`);
    console.log(`  MCP command: ${mcpCommand}`);
    console.log(`  Package: ${packageName}`);
    console.log(`  Runner: ${runnerType}`);
  }

  // Discover tools from MCP server
  if (!quiet) console.log(`  Discovering tools...`);

  let discovery;
  try {
    discovery = await discoverTools(packageName, {
      quiet: true,
      uvx: runnerType === "uvx",
      pip: runnerType === "pip",
      command: runnerType === "custom" || runnerType === "docker" ? mcpCommand : null,
    });
  } catch (error) {
    return { success: false, error: `Discovery failed: ${error.message}` };
  }

  if (!quiet) {
    console.log(`  Found ${discovery.tools.length} tools`);
  }

  // Group tools
  if (!quiet) console.log(`  Grouping tools...`);

  let groups;
  try {
    if (agentType) {
      groups = await groupToolsForExtension(discovery.serverName, discovery.tools, { quiet: true, agentType });
    } else {
      groups = fallbackGroupingForExtension(discovery.serverName, discovery.tools);
    }
  } catch (error) {
    if (!quiet) console.log(`  Grouping failed, using fallback...`);
    groups = fallbackGroupingForExtension(discovery.serverName, discovery.tools);
  }

  if (!quiet) {
    console.log(`  Created ${groups.length} groups`);
  }

  // Generate extension files
  if (!quiet) console.log(`  Generating extension...`);

  let files;
  try {
    files = generateExtensionFiles({
      name,
      serverName: discovery.serverName,
      mcpCommand: discovery.mcpCommand,
      packageName,
      groups,
      tools: discovery.tools,
      description: discovery.description,
    });
  } catch (error) {
    return { success: false, error: `Generation failed: ${error.message}` };
  }

  // Dry run output
  if (dryRun) {
    console.log(`\nDRY RUN: Would migrate "${name}" to extension`);
    console.log(`  Output: ~/.pi/agent/extensions/${name}/`);
    console.log(`  Files: ${Object.keys(files).join(", ")}`);
    if (cleanup) {
      console.log(`  Would remove: ~/agent-tools/${name}/`);
    }
    console.log("\nNo changes made.");
    return { success: true, dryRun: true };
  }

  // Write extension files
  if (!quiet) console.log(`  Writing extension...`);

  try {
    writeOutput(extPath, files, {
      dryRun: false,
      force,
      quiet: true,
      packageName: name,
      isExtension: true,
    });
  } catch (error) {
    return { success: false, error: `Failed to write extension: ${error.message}` };
  }

  // Cleanup old CLI tool if requested
  if (cleanup) {
    if (!quiet) console.log(`  Removing old CLI tool...`);
    removeTool(name, { dryRun: false, quiet: true });
  }

  if (!quiet) {
    console.log(`  Done!`);
  }

  return {
    success: true,
    extensionPath: extPath,
    toolsCount: discovery.tools.length,
    groupsCount: groups.length,
    cleanup,
  };
}

/**
 * Migrate all CLI tools to pi extensions
 * @param {object} options - Options
 * @param {boolean} options.dryRun - Preview without writing
 * @param {boolean} options.quiet - Suppress output
 * @param {boolean} options.cleanup - Remove old CLI tools after migration
 * @param {boolean} options.force - Overwrite existing extensions
 * @param {string} options.agentType - AI agent type for grouping
 * @returns {object} - Results object
 */
export async function migrateAll(options = {}) {
  const { dryRun = false, quiet = false, cleanup = false, force = false, agentType = null } = options;

  const tools = scanCliTools();

  if (tools.length === 0) {
    return {
      success: true,
      migrated: [],
      skipped: [],
      failed: [],
      message: "No CLI tools found in ~/agent-tools/",
    };
  }

  const migrateable = tools.filter((t) => t.canMigrate);
  const notMigrateable = tools.filter((t) => !t.canMigrate);

  if (!quiet) {
    console.log(`Found ${tools.length} CLI tools (${migrateable.length} migrateable)`);
    if (notMigrateable.length > 0) {
      console.log(`Skipping (no MCP command found): ${notMigrateable.map((t) => t.name).join(", ")}`);
    }
    console.log("");
  }

  const results = {
    success: true,
    migrated: [],
    skipped: notMigrateable.map((t) => t.name),
    failed: [],
  };

  for (const tool of migrateable) {
    const result = await migrateTool(tool.name, { dryRun, quiet, cleanup, force, agentType });

    if (result.success) {
      results.migrated.push(tool.name);
    } else {
      results.failed.push({ name: tool.name, error: result.error });
      results.success = false;
    }

    if (!quiet && !dryRun) {
      console.log("");
    }
  }

  return results;
}

/**
 * Format migration scan results for display
 * @param {Array} tools - Array of tool info objects
 * @returns {string} - Formatted string
 */
export function formatMigrationScan(tools) {
  if (tools.length === 0) {
    return `No CLI tools found in ~/agent-tools/`;
  }

  const lines = [];
  lines.push(`CLI Tools Available for Migration (${tools.length})`);
  lines.push("-".repeat(70));
  lines.push(`${"NAME".padEnd(20)}${"MCP COMMAND".padEnd(40)}STATUS`);

  for (const tool of tools) {
    const cmd = tool.mcpCommand
      ? tool.mcpCommand.length > 37
        ? tool.mcpCommand.slice(0, 34) + "..."
        : tool.mcpCommand
      : "(not found)";
    const status = tool.canMigrate ? "ready" : "skip";
    lines.push(`${tool.name.padEnd(20)}${cmd.padEnd(40)}${status}`);
  }

  lines.push("");
  const migrateable = tools.filter((t) => t.canMigrate).length;
  lines.push(`${migrateable} of ${tools.length} tools can be migrated`);
  lines.push("");
  lines.push(`To migrate: mcp2ext migrate [name] [--cleanup]`);
  lines.push(`            mcp2ext migrate --all [--cleanup]`);

  return lines.join("\n");
}

/**
 * Shell Config Manager
 * Handles auto-configuration of PATH in shell config files (.zshrc, .bashrc)
 */

import { existsSync, readFileSync, appendFileSync } from "fs";
import { homedir } from "os";
import { join } from "path";

const PATH_EXPORT = 'export PATH="$HOME/agent-tools/bin:$PATH"';
const COMMENT = "# Agent tools (mcp-to-pi-tools generated commands)";

/**
 * Detect current shell from environment
 * @returns {string} - "zsh", "bash", or "unknown"
 */
export function detectShell() {
  const shell = process.env.SHELL || "";
  if (shell.includes("zsh")) return "zsh";
  if (shell.includes("bash")) return "bash";
  return "unknown";
}

/**
 * Get path to shell config file based on detected shell
 * @returns {string|null} - Path to config file or null if unknown shell
 */
export function getShellConfigPath() {
  const shell = detectShell();
  if (shell === "zsh") return join(homedir(), ".zshrc");
  if (shell === "bash") return join(homedir(), ".bashrc");
  return null;
}

/**
 * Check if PATH is already configured in shell config
 * @param {string} configPath - Path to shell config file
 * @returns {boolean}
 */
export function isPathConfigured(configPath) {
  if (!configPath || !existsSync(configPath)) return false;
  const content = readFileSync(configPath, "utf-8");
  return content.includes("agent-tools/bin");
}

/**
 * Add PATH export to shell config file
 * @param {string} configPath - Path to shell config file
 * @returns {object} - Result with success, action, and optional error
 */
export function addPathToShellConfig(configPath) {
  if (!configPath) {
    return { success: false, error: "Unknown shell - cannot configure PATH" };
  }

  if (isPathConfigured(configPath)) {
    return { success: true, action: "exists", configPath };
  }

  try {
    appendFileSync(configPath, `\n${COMMENT}\n${PATH_EXPORT}\n`);
    return { success: true, action: "added", configPath };
  } catch (error) {
    return { success: false, error: error.message };
  }
}

/**
 * Configure shell PATH if needed
 * @returns {object} - Result with success, action, configPath, and optional error
 */
export function ensurePathConfigured() {
  const configPath = getShellConfigPath();
  return addPathToShellConfig(configPath);
}

/**
 * Configuration Manager
 * Handles loading config from settings files and CLI options
 */

import { existsSync, readFileSync } from "fs";
import { join } from "path";
import { homedir } from "os";

// Config paths
const CLI_CONFIG_PATH = join(homedir(), "agent-tools", "mcp2cli.settings.json");
const EXT_CONFIG_PATH = join(homedir(), ".pi", "agent", "mcp2ext.settings.json");

const DEFAULT_CONFIG = {
  register: true,
  registerPaths: [],
  symlink: true,
  symlinkDir: "~/agent-tools/bin",
};

// Preset paths for agent config files (used by CLI mode)
export const PRESETS = {
  pi: "~/.pi/agent/AGENTS.md",
  claude: "~/.claude/CLAUDE.md",
  gemini: "~/.gemini/AGENTS.md",
  codex: "~/.codex/AGENTS.md",
};

export const PRESET_PRIORITY = [
  "~/.pi/agent/AGENTS.md",
  "~/.claude/CLAUDE.md",
  "~/.codex/AGENTS.md",
  "~/.gemini/AGENTS.md",
];

/**
 * Load config from file, merging with defaults
 * @param {boolean} [isExtension=false] - Whether to load extension config
 * @returns {object} - Config object
 */
export function loadConfig(isExtension = false) {
  const configPath = isExtension ? EXT_CONFIG_PATH : CLI_CONFIG_PATH;

  if (!existsSync(configPath)) {
    return { ...DEFAULT_CONFIG };
  }

  try {
    const content = readFileSync(configPath, "utf-8");
    const fileConfig = JSON.parse(content);
    return {
      ...DEFAULT_CONFIG,
      ...fileConfig,
    };
  } catch (error) {
    console.warn(`Warning: Failed to parse config file: ${error.message}`);
    return { ...DEFAULT_CONFIG };
  }
}

/**
 * Resolve preset name to path
 * @param {string} name - Preset name (pi, claude, gemini, codex)
 * @returns {string|null} - Path or null if not found
 */
export function resolvePreset(name) {
  return PRESETS[name.toLowerCase()] || null;
}

/**
 * Get all available preset names
 * @returns {string[]} - Array of preset names
 */
export function getPresetNames() {
  return Object.keys(PRESETS);
}

/**
 * Merge config with CLI options (CLI takes precedence)
 * @param {object} config - Loaded config
 * @param {object} options - CLI options
 * @returns {object} - Merged effective config
 */
export function mergeWithCli(config, options) {
  const effective = { ...config };

  if (options.register === false) {
    effective.register = false;
  }

  const paths = new Set();

  if (options.registerPaths && options.registerPaths.length > 0) {
    options.registerPaths.forEach((p) => paths.add(p));
  }

  if (options.presets && options.presets.length > 0) {
    for (const preset of options.presets) {
      const path = resolvePreset(preset);
      if (path) {
        paths.add(path);
      } else {
        console.warn(`Warning: Unknown preset "${preset}". Available: ${getPresetNames().join(", ")}`);
      }
    }
  }

  if (paths.size > 0) {
    effective.registerPaths = Array.from(paths);
  }

  effective.local = options.local || false;
  effective.allPresets = options.allPresets || false;

  if (options.symlink === false) {
    effective.symlink = false;
  }
  if (options.symlinkDir) {
    effective.symlinkDir = options.symlinkDir;
  }
  if (options.forceSymlink) {
    effective.forceSymlink = true;
  }

  return effective;
}

/**
 * Get config file path (for display/help)
 * @param {boolean} [isExtension=false] - Whether to get extension config path
 * @returns {string}
 */
export function getConfigPath(isExtension = false) {
  return isExtension ? EXT_CONFIG_PATH : CLI_CONFIG_PATH;
}

/**
 * Tool Management
 * Handles listing, removing, and refreshing installed tools (CLI and extensions)
 */

import { readdirSync, statSync, existsSync, rmSync, readFileSync } from "fs";
import { join } from "path";
import { homedir } from "os";
import { readManifest } from "./output.js";
import { loadRegistry, findSectionByHeading, resolvePath, unregisterEntry, removeFromRegistry, registerToAll, resolveAllPaths, registerEntry } from "./registration.js";
import { removeSymlinksForTool, getDefaultSymlinkDir, createSymlinksForTool } from "./symlink.js";
import { PRESETS } from "./config.js";

const AGENT_TOOLS_DIR = join(homedir(), "agent-tools");
const EXTENSIONS_DIR = join(homedir(), ".pi", "agent", "extensions");

// ============================================================================
// CLI Tool Management (Legacy)
// ============================================================================

export function deriveHeading(name) {
  const displayName = name.split("-").map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
  return `### ${displayName} Tools`;
}

export function getToolHeading(name) {
  return deriveHeading(name);
}

export function listInstalledTools() {
  if (!existsSync(AGENT_TOOLS_DIR)) return [];

  const entries = readdirSync(AGENT_TOOLS_DIR);
  const tools = [];

  for (const entry of entries) {
    if (entry === "bin") continue;
    const toolPath = join(AGENT_TOOLS_DIR, entry);
    try {
      if (statSync(toolPath).isDirectory()) {
        tools.push(getToolInfo(entry, toolPath));
      }
    } catch {
      continue;
    }
  }

  return tools;
}

export function getToolInfo(name, toolPath) {
  const manifest = readManifest(toolPath);
  const heading = getToolHeading(name);
  const registeredIn = checkRegistrationStatus(heading);

  let scripts = [];
  if (manifest?.files) {
    scripts = manifest.files.filter(f => f.endsWith(".js"));
  } else {
    try {
      scripts = readdirSync(toolPath).filter(f => f.endsWith(".js"));
    } catch {
      scripts = [];
    }
  }

  const symlinkDir = resolvePath(getDefaultSymlinkDir());
  let symlinkCount = 0;
  if (existsSync(symlinkDir)) {
    for (const script of scripts) {
      const symlinkName = script.replace(/\.js$/, "");
      const linkPath = join(symlinkDir, symlinkName);
      if (existsSync(linkPath)) {
        symlinkCount++;
      }
    }
  }

  return {
    name,
    path: toolPath,
    scripts: scripts.length,
    scriptNames: scripts,
    registeredIn,
    symlinks: `${symlinkCount}/${scripts.length}`,
    hasManifest: !!manifest,
    heading
  };
}

export function checkRegistrationStatus(heading) {
  const registered = [];

  for (const [presetName, presetPath] of Object.entries(PRESETS)) {
    const resolvedPath = resolvePath(presetPath);
    if (!existsSync(resolvedPath)) continue;

    try {
      const content = readFileSync(resolvedPath, "utf-8");
      if (findSectionByHeading(content, heading)) {
        registered.push(presetName);
      }
    } catch {
      continue;
    }
  }

  return registered;
}

export function formatToolList(tools) {
  if (tools.length === 0) {
    return `No tools installed in ~/agent-tools/`;
  }

  const lines = [];
  lines.push(`Installed Tools (${tools.length})`);
  lines.push("-".repeat(67));
  lines.push(`${"NAME".padEnd(18)}${"SCRIPTS".padEnd(9)}${"REGISTERED".padEnd(14)}SYMLINKS`);

  for (const tool of tools) {
    const registered = tool.registeredIn.length > 0 ? tool.registeredIn.join(", ") : "(none)";
    lines.push(
      `${tool.name.padEnd(18)}${String(tool.scripts).padEnd(9)}${registered.padEnd(14)}${tool.symlinks}`
    );
  }

  lines.push("");
  lines.push(`Symlink directory: ~/agent-tools/bin`);

  return lines.join("\n");
}

export function removeTool(name, options = {}) {
  const { dryRun = false, quiet = false } = options;

  if (!name || name === "bin") {
    return { success: false, error: `Tool "${name}" not found in ~/agent-tools/` };
  }

  const toolPath = join(AGENT_TOOLS_DIR, name);

  if (!toolPath.startsWith(AGENT_TOOLS_DIR + "/")) {
    return { success: false, error: `Tool "${name}" not found in ~/agent-tools/` };
  }

  if (!existsSync(toolPath) || !statSync(toolPath).isDirectory()) {
    return { success: false, error: `Tool "${name}" not found in ~/agent-tools/` };
  }

  const heading = getToolHeading(name);
  const registry = loadRegistry();

  if (dryRun) {
    const symlinkDir = resolvePath(getDefaultSymlinkDir());
    const symlinks = [];
    if (existsSync(symlinkDir)) {
      const scripts = readdirSync(toolPath).filter(f => f.endsWith(".js"));
      for (const script of scripts) {
        const symlinkName = script.replace(/\.js$/, "");
        const linkPath = join(symlinkDir, symlinkName);
        if (existsSync(linkPath)) {
          symlinks.push(`~/agent-tools/bin/${symlinkName}`);
        }
      }
    }

    const registrations = [];
    for (const presetPath of Object.values(PRESETS)) {
      const resolvedPath = resolvePath(presetPath);
      if (existsSync(resolvedPath)) {
        try {
          const content = readFileSync(resolvedPath, "utf-8");
          if (findSectionByHeading(content, heading)) {
            registrations.push(presetPath);
          }
        } catch {
          continue;
        }
      }
    }

    const regEntry = registry.registrations[name];
    const customPaths = regEntry?.customPaths || regEntry?.paths || [];
    for (const p of customPaths) {
      if (!registrations.includes(p)) {
        registrations.push(p);
      }
    }

    console.log(`DRY RUN: Would remove tool "${name}"\n`);
    console.log("Would remove:");
    if (symlinks.length > 0) {
      console.log(`  - Symlinks: ${symlinks.join(", ")}`);
    }
    if (registrations.length > 0) {
      console.log(`  - Registrations: ${registrations.join(", ")}`);
    }
    console.log(`  - Directory: ~/agent-tools/${name}`);
    console.log("\nNo changes made.");

    return { success: true, dryRun: true };
  }

  if (!quiet) console.log(`Removing tool: ${name}\n`);

  if (!quiet) process.stdout.write("  [1/4] Removing symlinks... ");
  const symlinkResults = removeSymlinksForTool(toolPath);
  const removedSymlinks = symlinkResults.filter(r => r.success).length;
  if (!quiet) console.log(`done (${removedSymlinks} removed)`);

  if (!quiet) process.stdout.write("  [2/4] Removing registrations... ");
  let removedRegistrations = 0;

  for (const presetPath of Object.values(PRESETS)) {
    const result = unregisterEntry(presetPath, heading);
    if (result.action === "removed") removedRegistrations++;
  }

  const regEntry = registry.registrations[name];
  const customPaths = regEntry?.customPaths || regEntry?.paths || [];
  for (const p of customPaths) {
    const result = unregisterEntry(p, heading);
    if (result.action === "removed") removedRegistrations++;
  }
  if (!quiet) console.log(`done (${removedRegistrations} removed)`);

  if (!quiet) process.stdout.write("  [3/4] Updating registry... ");
  removeFromRegistry(name);
  if (!quiet) console.log("done");

  if (!quiet) process.stdout.write("  [4/4] Removing directory... ");
  rmSync(toolPath, { recursive: true });
  if (!quiet) console.log("done");

  if (!quiet) console.log(`\nTool "${name}" removed successfully.`);

  return { success: true };
}

export function generateBasicEntry(name, scripts) {
  const heading = deriveHeading(name);
  const toolList = scripts
    .map(s => s.replace(/\.js$/, ""))
    .map(s => `**${s}** - ${name} tool`)
    .join("\n");
  return `${heading}\n\n${toolList}`;
}

export function refreshTool(name, options = {}) {
  const { dryRun = false, quiet = false } = options;
  const toolPath = join(AGENT_TOOLS_DIR, name);
  const results = { symlinks: { created: 0, unchanged: 0 }, registrationAction: "none", registrationTargets: [] };

  if (!existsSync(toolPath)) {
    return { success: false, error: `Tool "${name}" not found` };
  }

  const scripts = readdirSync(toolPath).filter(f => f.endsWith(".js"));

  if (!dryRun) {
    const symlinkResults = createSymlinksForTool(toolPath, { quiet });
    results.symlinks.created = symlinkResults.filter(r => r.action === "created").length;
    results.symlinks.unchanged = symlinkResults.filter(r => r.action === "unchanged").length;
  } else {
    const symlinkDir = resolvePath(getDefaultSymlinkDir());
    let existingCount = 0;
    if (existsSync(symlinkDir)) {
      for (const script of scripts) {
        const symlinkName = script.replace(/\.js$/, "");
        if (existsSync(join(symlinkDir, symlinkName))) {
          existingCount++;
        }
      }
    }
    results.symlinks.created = scripts.length - existingCount;
    results.symlinks.unchanged = existingCount;
  }

  const heading = getToolHeading(name);
  const registered = checkRegistrationStatus(heading);
  const entry = generateBasicEntry(name, scripts);

  if (registered.length === 0) {
    const paths = resolveAllPaths({ registerPaths: [], allPresets: false });
    if (paths.length > 0) {
      results.registrationAction = "added";
      results.registrationTargets = paths;
      if (!dryRun) {
        registerToAll(paths, entry, name, { quiet });
      }
    }
  } else {
    results.registrationAction = "updated";
    results.registrationTargets = registered;
    if (!dryRun) {
      for (const preset of registered) {
        const path = PRESETS[preset];
        registerEntry(resolvePath(path), entry, name);
      }
    }
  }

  return { success: true, ...results };
}

export function refreshAllTools(options = {}) {
  const tools = listInstalledTools();
  return tools.map(t => ({ name: t.name, ...refreshTool(t.name, options) }));
}

