/**
 * List installed MCP extensions
 * @returns {Array} - Array of extension info objects
 */
export function listInstalledExtensions() {
  if (!existsSync(EXTENSIONS_DIR)) return [];

  const entries = readdirSync(EXTENSIONS_DIR);
  const extensions = [];

  for (const entry of entries) {
    const extPath = join(EXTENSIONS_DIR, entry);
    try {
      if (statSync(extPath).isDirectory()) {
        extensions.push(getExtensionInfo(entry, extPath));
      }
    } catch {
      continue;
    }
  }

  return extensions;
}

/**
 * Get info about a specific extension
 * @param {string} name - Extension name
 * @param {string} extPath - Extension directory path
 * @returns {object} - Extension info
 */
export function getExtensionInfo(name, extPath) {
  const manifest = readManifest(extPath, true);
  const hasIndex = existsSync(join(extPath, "index.ts"));
  const hasPackageJson = existsSync(join(extPath, "package.json"));

  let mcpPackage = null;
  let mcpCommand = null;

  if (hasPackageJson) {
    try {
      const pkg = JSON.parse(readFileSync(join(extPath, "package.json"), "utf-8"));
      mcpPackage = pkg.mcp?.package;
      mcpCommand = pkg.mcp?.command;
    } catch {
      // Ignore parse errors
    }
  }

  return {
    name,
    path: extPath,
    hasIndex,
    hasPackageJson,
    hasManifest: !!manifest,
    mcpPackage,
    mcpCommand,
    generatedAt: manifest?.generatedAt,
  };
}

/**
 * Format extension list for display
 * @param {Array} extensions - Array of extension info objects
 * @returns {string} - Formatted string
 */
export function formatExtensionList(extensions) {
  if (extensions.length === 0) {
    return `No MCP extensions installed in ~/.pi/agent/extensions/`;
  }

  const lines = [];
  lines.push(`Installed MCP Extensions (${extensions.length})`);
  lines.push("-".repeat(60));
  lines.push(`${"NAME".padEnd(25)}${"MCP PACKAGE".padEnd(30)}STATUS`);

  for (const ext of extensions) {
    const pkg = ext.mcpPackage || "(unknown)";
    const status = ext.hasIndex ? "ready" : "invalid";
    lines.push(
      `${ext.name.padEnd(25)}${pkg.padEnd(30)}${status}`
    );
  }

  lines.push("");
  lines.push(`Extensions directory: ~/.pi/agent/extensions/`);

  return lines.join("\n");
}

/**
 * Remove an extension
 * @param {string} name - Extension name
 * @param {object} options - Options
 * @param {boolean} options.dryRun - Preview without removing
 * @param {boolean} options.quiet - Suppress output
 * @returns {object} - Result object
 */
export function removeExtension(name, options = {}) {
  const { dryRun = false, quiet = false } = options;

  if (!name) {
    return { success: false, error: `Extension name required` };
  }

  const extPath = join(EXTENSIONS_DIR, name);

  if (!extPath.startsWith(EXTENSIONS_DIR + "/")) {
    return { success: false, error: `Extension "${name}" not found in ~/.pi/agent/extensions/` };
  }

  if (!existsSync(extPath) || !statSync(extPath).isDirectory()) {
    return { success: false, error: `Extension "${name}" not found in ~/.pi/agent/extensions/` };
  }

  if (dryRun) {
    console.log(`DRY RUN: Would remove extension "${name}"\n`);
    console.log("Would remove:");
    console.log(`  - Directory: ~/.pi/agent/extensions/${name}`);
    console.log("\nNo changes made.");
    return { success: true, dryRun: true };
  }

  if (!quiet) console.log(`Removing extension: ${name}\n`);

  if (!quiet) process.stdout.write("  Removing directory... ");
  rmSync(extPath, { recursive: true });
  if (!quiet) console.log("done");

  if (!quiet) console.log(`\nExtension "${name}" removed successfully.`);

  return { success: true };
}

